syllabus.css.content:
/* ===== ROOT VARIABLES ===== */
:root {
    --primary: #1e88e5;
    --primary-light: #42a5f5;
    --danger: #b00020;
    --bg: #f2f2f2;
    --card-bg: #ffffff;
    --text: #000;
    --radius: 10px;
    --shadow: 0 1px 4px rgba(0,0,0,0.08);
    --btn-shadow: 0 3px 5px rgba(0,0,0,0.15);
}

/* ===== RESET ===== */
*,
*::before,
*::after {
    box-sizing: border-box;
    -webkit-tap-highlight-color: transparent;
}

/* ===== 🚀 PRELOAD (NO FLICKER - IMPORTANT) ===== */
html.preload body {
    opacity: 0;
    visibility: hidden;
}

html.loaded body {
    opacity: 1;
    visibility: visible;
    transition: opacity 0.25s ease;
}

/* ===== BODY ===== */
body {
    margin: 0;
    font-family: 'Ubuntu', sans-serif;
    background: var(--bg);
    color: var(--text);
}

/* ===== REMOVE UNUSED UI ===== */
.topbar,
.sidebar,
.menu-overlay,
.menu-btn,
.brand-logo {
    display: none !important;
}

/* ===== LAYOUT ===== */
.content {
    padding: 10px;
}

/* ===== HEADER ===== */
.page-header {
    display: flex;
    flex-direction: column;
    text-align: center;
    background: var(--card-bg);
    border-radius: var(--radius);
    padding: 10px 12px;
    margin-bottom: 10px;
    box-shadow: var(--shadow);
}

.page-subtitle {
    order: 1;
    font-size: 15px;
    font-weight: 600;
    color: var(--primary);
    margin: 0;
}

.page-title {
    order: 2;
    font-size: 13px;
    color: var(--danger);
    margin: 2px 0;
}

/* ===== INFO CARD ===== */
.info-card {
    background: transparent;
    box-shadow: none;
    padding: 6px 0 0;
    margin: 0;
}

/* ===== CREDITS ===== */
#credits-toggle {
    cursor: pointer;
    font-size: 13px;
    font-weight: 600;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 6px 0;
    border-top: 1px solid #eee;
    margin-top: 6px;
}

#credits-table-container {
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.3s ease;
}

#credits-table-container.expanded {
    max-height: 600px;
}

/* ===== TABLE ===== */
table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 6px;
}

th, td {
    padding: 6px 8px;
    text-align: left;
    font-size: 12px;
    border-bottom: 1px solid #ddd;
}

th {
    background: #f5f5f5;
    font-weight: 600;
}

/* ===== BUTTON LIST ===== */
.syllabus-tabs {
    display: flex;
    flex-direction: column;
    gap: 12px;
}

/* ===== TAB BUTTON ===== */
.tab-btn {
    color: white;
    padding: 14px;
    border-radius: var(--radius);
    border: none;
    font-size: 14px;
    font-weight: 600;
    text-align: center;
    box-shadow: var(--btn-shadow);
    transition: transform 0.15s ease;
}

.tab-btn[data-type="theory"] {
    background: linear-gradient(90deg, var(--primary-light), var(--primary));
}

.tab-btn[data-type="lab"] {
    background: linear-gradient(90deg, #ff8f00, #ff6f00);
}

.tab-btn:active {
    transform: scale(0.97);
}

/* ===== SUBJECT CONTENT ===== */
.subject-card ul,
.unit-topics {
    padding-left: 16px;
    margin-left: 0;
}

.subject-card li {
    margin-left: 0;
    padding-left: 0;
}

.subject-card h2 {
    color: var(--primary);
}

/* ===== LIST ===== */
.unit-title {
    font-weight: 600;
    font-size: 14px;
    margin-top: 8px;
}

.unit-topics li {
    margin-bottom: 12px;
}

/* ===== ACTION BUTTONS ===== */
.ask-ai-topic-button,
.search-youtube-button,
.mark-complete-button {
    border: none;
    padding: 3px 6px;
    font-size: 10px;
    border-radius: 4px;
    margin-left: 5px;
    cursor: pointer;
}

.ask-ai-topic-button {
    background: #e3f2fd;
    color: #1565c0;
}

.search-youtube-button {
    background: #ffebee;
    color: #c62828;
}

.mark-complete-button {
    background: #e8f5e9;
    color: #2e7d32;
}

/* ===== COMPLETED ===== */
.topic-completed {
    opacity: 0.4;
}

/* ===== GO TO TOP ===== */
#goToTopBtn {
    position: fixed;
    bottom: 18px;
    right: 18px;
    width: 42px;
    height: 42px;
    border-radius: 50%;
    background: #333;
    color: white;
    border: none;
    cursor: pointer;
    transition: opacity 0.3s ease;
}

/* ===== MODAL ===== */
.modal-content {
    background: #ffffff !important;border: 1px solid #dddddd !important;
    color: #000;
    border: none;
}

#modal-title {
    color: #1e88e5 !important;
    text-align: center;
}

.modal-option-btn {
    background: linear-gradient(90deg, #42a5f5, #1e88e5) !important;
    color: #ffffff !important;
    border-radius: var(--radius);
}
.modal-close-btn {
    color: #333333 !important;
}
/* ===== ELECTIVE CONTENT ===== */
.modal-content ul {
    padding-left: 18px;
    margin-left: 0;
}

.modal-content li {
    margin-left: 0;
    padding-left: 0;
}

.modal-content li strong,
.modal-content li .unit-title {
    display: block;
    margin-left: -18px;
    font-weight: 600;
    color: var(--primary);
}

